// Cascada: un servicio de despachos con 20 hilos; el cotizador externo se cuelga entre los 20 s y los 50 s.
function mulberry(a){return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function latProv(t,r){ return (t>=20000&&t<50000)?15000:80+r()*80 } // ms
function sim(cfg){
  const r=mulberry(7), main=new Array(20).fill(0), prov=new Array(cfg.bulk||0).fill(0);
  const S={cot:{ok:0,fb:0,err:0},loc:{ok:0,err:0},enProv:0};
  let fallos=0, abierto=-1, sonda=false;
  for(let t=0;t<90000;t+=20){               // 50 pedidos por segundo
    const esCot=r()<0.7, lat=latProv(t,r);
    const pool=(esCot&&cfg.bulk)?prov:main;
    let i=0; for(let k=1;k<pool.length;k++) if(pool[k]<pool[i]) i=k;
    const espera=Math.max(0,pool[i]-t);
    const tope=(esCot&&cfg.bulk)?0:1000;     // el mamparo falla rápido; el pool común deja esperar 1 s
    if(espera>tope){ (esCot?S.cot.err++:S.loc.err++); continue; }
    if(!esCot){ pool[i]=t+espera+20; (espera+20<=1000)?S.loc.ok++:S.loc.err++; continue; }
    if(cfg.breaker&&abierto>=0){
      if(t-abierto<5000){ cfg.fb?S.cot.fb++:S.cot.err++; continue; }      // abierto: ni llamamos
      if(sonda){ cfg.fb?S.cot.fb++:S.cot.err++; continue; } sonda=true;   // semiabierto: una sola sonda
    }
    S.enProv++;
    const dur=cfg.timeout?Math.min(lat,cfg.timeout):lat;
    pool[i]=t+espera+dur;
    const falla=cfg.timeout&&lat>cfg.timeout;
    if(falla){ fallos++; if(cfg.breaker&&(fallos>=5||sonda)){abierto=t;fallos=0;} sonda=false; cfg.fb?S.cot.fb++:S.cot.err++; }
    else { fallos=0; if(sonda){abierto=-1;sonda=false;} (espera+dur<=1000)?S.cot.ok++:S.cot.err++; }
  }
  return S;
}
const casos=[["A sin protecciones",{}],["B timeout 800 ms",{timeout:800}],["C B + mamparo de 8 hilos",{timeout:800,bulk:8}],["D B + breaker + plan B",{timeout:800,breaker:1,fb:1}]];
console.log("caso | local ok/err | cotiz ok/plan B/err | pedidos al proveedor");
for(const [n,c] of casos){const s=sim(c);console.log(n,"|",s.loc.ok+"/"+s.loc.err,"|",s.cot.ok+"/"+s.cot.fb+"/"+s.cot.err,"|",s.enProv)}

// 1000 clientes llaman a un cotizador que está caído hasta los 5 s y después atiende 100 pedidos por segundo.
function mulberry(a){return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function correr(nombre, espera){
  const r=mulberry(42), N=1000, CAP=100, VUELVE=5000;
  let cola=[]; for(let i=0;i<N;i++) cola.push({t:Math.floor(r()*100),n:0});  // todos arrancan en el mismo instante (±100 ms)
  const porSeg={}, atendidos={}; const fines=[]; let despues=0, intentos=0, fin=0, hechos=0;
  while(cola.length&&intentos<100000){
    cola.sort((a,b)=>a.t-b.t);
    const c=cola.shift(), seg=Math.floor(c.t/1000); intentos++; if(c.t>=VUELVE){despues++; porSeg[seg]=(porSeg[seg]||0)+1;}
    const ok=c.t>=VUELVE && (atendidos[seg]=(atendidos[seg]||0))<CAP;
    if(ok){atendidos[seg]++;hechos++;fin=c.t;fines.push(c.t);} else if(c.n<30){ c.n++; c.t+=espera(c.n,r); cola.push(c);} 
  }
  const pico=Math.max(...Object.values(porSeg));
  console.log(nombre.padEnd(34),"pedidos tras la vuelta:",String(despues).padStart(6),"| pico por segundo:",String(pico).padStart(5),"| atendidos:",hechos,"| p50 / p95:",(fines.sort((a,b)=>a-b)[499]/1000).toFixed(1)+" / "+(fines[949]/1000).toFixed(1),"s");
}
const base=500, tope=30000;
correr("espera fija de 1 s",()=>1000);
correr("exponencial sin jitter",(n)=>Math.min(tope,base*2**(n-1)));
correr("exponencial con full jitter",(n,r)=>r()*Math.min(tope,base*2**(n-1)));

// Las tres piezas chicas, con un proveedor falso que falla las dos primeras veces.
function semilla(a){return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
const azar = semilla(3);

function conTimeout(promesa, ms) {
  let reloj;
  const corte = new Promise((_, rechazo) => { reloj = setTimeout(() => rechazo(new Error("timeout " + ms + " ms")), ms); });
  return Promise.race([promesa, corte]).finally(() => clearTimeout(reloj));
}

async function conReintentos(llamar, { intentos = 4, base = 20, tope = 200 } = {}) {
  for (let n = 1; ; n++) {
    try { return await llamar(n); }
    catch (e) {
      if (n === intentos) throw e;
      const espera = azar() * Math.min(tope, base * 2 ** (n - 1));   // full jitter
      console.log(`intento ${n} falló (${e.message}); espero ${espera.toFixed(0)} ms`);
      await new Promise((r) => setTimeout(r, espera));
    }
  }
}

const proveedor = (n) => new Promise((ok, mal) => {
  if (n === 1) return;                                  // se cuelga: no responde nunca
  if (n === 2) return setTimeout(() => mal(new Error("500")), 5);
  setTimeout(() => ok({ tarifa: 4900 }), 5);
});

const r = await conReintentos((n) => conTimeout(proveedor(n), 50));
console.log("resultado:", JSON.stringify(r));

// Un servicio con 20 hilos y 20 ms por pedido atiende como máximo 1000 pedidos por segundo.
// Durante 10 s le llegan 1500 por segundo. El cliente se rinde si no tiene respuesta en 1 s.
function correr(nombre, maxEspera){
  const hilos=new Array(20).fill(0); let util=0, tarde=0, rechazados=0, total=0;
  for(let t=0;t<10000;t+=1000/1500){
    total++;
    let i=0; for(let k=1;k<20;k++) if(hilos[k]<hilos[i]) i=k;
    const espera=Math.max(0,hilos[i]-t);
    if(espera>maxEspera){ rechazados++; continue; }          // se rechaza al instante, casi sin costo
    hilos[i]=t+espera+20;                                     // el servidor trabaja igual, aunque el cliente ya se haya ido
    (espera+20<=1000)?util++:tarde++;
  }
  console.log(nombre.padEnd(30),"recibidos:",total,"| respuestas útiles:",String(util).padStart(5),"| trabajo tirado:",String(tarde).padStart(5),"| rechazados:",rechazados);
}
